 chart:<><path d=\"M4 4v16h16M8 15l4-5 4 3 5-7\"/></>,folder:<path d=\"M3 7V5a2 2 0 0 1 2-2h5l3 4h6a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7Z\"/>,users:<><circle cx=\"9\" cy=\"8\" r=\"3\"/><path d=\"M3 20v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 5\"/></>,plus:<path d=\"M12 5v14M5 12h14\"/>,chevron:<path d=\"m9 5 7 7-7 7\"/>,search:<><circle cx=\"10.5\" cy=\"10.5\" r=\"6.5\"/><path d=\"m16 16 5 5\"/></>,bell:<><path d=\"M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4\"/></>,arrow:<path d=\"M5 17 18 4M6 4h12v12\"/>,calendar:<><rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"3\"/><path d=\"M7 3v4m10-4v4M3 11h18m-12 5h.01m4 0h.01m4 0h.01\"/></>,sliders:<><path d=\"M4 7h7m4 0h5M4 17h3m4 0h9\"/><circle cx=\"13\" cy=\"7\" r=\"2\"/><circle cx=\"9\" cy=\"17\" r=\"2\"/></>,grip:<>{[7,12,17].map(y=><g key={y}><circle cx=\"9\" cy={y} r=\".7\"/><circle cx=\"15\" cy={y} r=\".7\"/></g>)}</>,more:<>{[5,12,19].map(x=><circle key={x} cx={x} cy=\"12\" r=\"1\"/>)}</>,close:<path d=\"m6 6 12 12M6 18 18 6\"/>,check:<path d=\"m5 12 4 4L19 6\"/>,external:<><path d=\"M14 3h7v7m0-7L10 14M10 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-5\"/></>,help:<><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 3h.01\"/></>,logout:<><path d=\"M9 4H4v16h5m5-13 5 5-5 5m-6-5h11\"/></>,wallet:<><rect x=\"3\" y=\"5\" width=\"18\" height=\"15\" rx=\"3\"/><path d=\"M3 8V5l13-3v3m5 7h-6v5h6m-3-2.5h.01\"/></>,cart:<><path d=\"M2 3h3l3 12h11l3-9H6\"/><circle cx=\"10\" cy=\"20\" r=\"1\"/><circle cx=\"18\" cy=\"20\" r=\"1\"/></>,target:<><circle cx=\"12\" cy=\"12\" r=\"9\"/><circle cx=\"12\" cy=\"12\" r=\"5\"/><circle cx=\"12\" cy=\"12\" r=\"1\"/></>,clock:<><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3 2\"/></>,download:<><path d=\"M12 3v12m-4-4 4 4 4-4M4 15v6h16v-6\"/></>,star:<path d=\"m12 3 3 6 6 1-4.5 4.5 1 6.5L12 18l-5.5 3 1-6.5L3 10l6-1Z\"/>};
