type WidgetType='revenue'|'orders'|'customers'|'conversion'|'chart'|'traffic'|'projects'|'activity';
type Widget={id:string;type:WidgetType;x:number;y:number;w:number;h:number};
const titles:Record<WidgetType,string>={revenue:'Общая выручка',orders:'Заказы',customers:'Новые клиенты',conversion:'Конверсия',chart:'Динамика выручки',traffic:'Источники трафика',projects:'Проекты',activity:'Последняя активность'};
const defaults:Widget[]=[...(['revenue','orders','customers','conversion'] as WidgetType[]).map((type,i)=>({id:type,type,x:i*3,y:0,w:3,h:1})),{id:'chart',type:'chart',x:0,y:1,w:8,h:2},{id:'traffic',type:'traffic',x:8,y:1,w:4,h:2},{id:'projects',type:'projects',x:0,y:3,w:8,h:2},{id:'activity',type:'activity',x:8,y:3,w:4,h:2}];
const overlap=(a:Widget,b:Widget)=>a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;
function relocate(items:Widget[],id:string,x:number,y:number){const original=items.find(i=>i.id===id)"'!;const moved={...original,x:Math.max(0,Math.min(12-original.w,x)),y:Math.max(0,y)};const next=items.map(i=>i.id===id?moved:{...i});const collisions=next.filter(i=>i.id!==id&&overlap(i,moved));if(collisions.length===1&&collisions[0].w===original.w&&collisions[0].h===original.h){collisions[0].x=original.x;collisions[0].y=original.y;}else{const placed=[moved,...next.filter(i=>i.id!==id&&!collisions.includes(i))];for(const c of collisions){c.y=moved.y+moved.h;while(placed.some(p=>overlap(c,p)))c.y++;placed.push(c);}}return next;}
const projects=[{name:'"'Редизайн сайта',caption:'Дизайн и разработка',icon:'↗',color:'purple',people:['АК','МС','ДВ'],progress:72,status:'В работе',date:'28 июня'},{name:'Летняя кампания',caption:'Маркетинг',icon:'◈',color:'orange',people:['ЕП','АН'],progress:45,status:'В работе',date:'30 июня'},{name:'Мобильное приложение',caption:'Разработка продукта',icon:'▤',color:'blue',people:['ДВ','АК','МС'],progress:90,status:'На проверке',date:'25 июня'}];
const activity=[{initial:'АК',name:'Анна Кузнецова',action:'завершила задачу',subject:'Дизайн главной страницы',time:'5 минут назад',color:'purple'},{initial:'МС',name:'Михаил Соколов',action:'добавил новый проект',subject:'Летняя кампания',time:'24 минуты назад',color:'peach'},{initial:'ЕП',name:'Елена Петрова',action:'обновила отчёт',subject:'Аналитика за июнь',time:'1 час назад',color:'green'}];
function Sparkline({variant=0}:{variant?:number}) {const lines=['0,38 10,32 20,34 30,27 40,30 50,15 60,19 70,10 80,15 90,5 100,9 110,1','0,35 10,36 20,24 30,29 40,19 50,24 60,12 70,17 80,8 90,11 100,3 110,6','0,35 10,29 20,32 30,19 40,25 50,16 60,21 70,10 80,15 90,3 100,8 110,1','0,34 10,25 20,30 30,20 40,26 50,12 60,17 70,9 80,16 90,8 100,12 110,3'];return <svg className=\"sparkline\" viewBox=\"0 0 110 45\"><defs><linearGradient id={"'`spark${variant}`} x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#159778" stopOpacity=".14"/><stop offset="1" stopColor="#159778" stopOpacity="0"/></linearGradient></defs><polygon points={`0,45 ${lines[variant]} 110,45`} fill={`url(#spark${variant})`}/><polyline points={lines[variant]} fill="none" stroke="#249b7e" strokeWidth="1.7" strokeLinejoin="round"/></svg>}
function RevenueChart({period}:{period:string}){const [hover,setHover]=useState<number|null>(null);const factor=period==='"'7 дней'?.72:period==='90 дней'?1.15:1;const vals=[94,119,107,92,119,169,136,155,142,112,134,181,169,205,162,188,221,203,245,227,239,273,235,260,298,263,277,314,286,325];const pts=vals.map((v,i)=>"'`${42+i*21.25},${213-v*.54*factor}`);const prior=vals.map((v,i)=>`${42+i*21.25},${226-(v*.35+(i%3)*16)*factor}`);return <><div className="chart-summary"><span className="chart-total">₽ 1 284 560</span><span className="trend">↗ 12,8%</span><span className="chart-comparison">к прошлому периоду</span><div className="legend"><span><i/>Текущий период</span><span><i className="previous"/>Прошлый период</span></div></div><div className="chart-plot" onMouseLeave={()=>setHover(null)}><svg viewBox="0 0 690 265" preserveAspectRatio="none" role="img" aria-label="График роста выручки за июнь"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stopColor="#249e81" stopOpacity=".15"/><stop offset="1" stopColor="#249e81" stopOpacity=".01"/></linearGradient></defs>{[0,1,2,3,4].map((_,i)=><g key={i}><line x1="42" x2="667" y1={25+i*49} y2={25+i*49} stroke="#ebeeed" strokeDasharray="3 4"/><text x="0" y={29+i*49} fill="#939b98" fontSize="10">{160-i*40} тыс.</text></g>)}<polygon points={`42,221 ${pts.join('"' ')} 658,221"'`} fill="url(#chart-fill)"/><polyline points={prior.join('"' ')} fill=\"none\" stroke=\"#c6cfca\" strokeWidth=\"2\" strokeDasharray=\"5 5\"/><polyline points={pts.join(' ')} fill=\"none\" stroke=\"#279a7c\" strokeWidth=\"2.6\" strokeLinejoin=\"round\" strokeLinecap=\"round\"/>{['1 июн','5 июн','10 июн','15 июн','20 июн','25 июн','30 июн'].map((v,i)=><text key={v} x={42+i*102} y=\"251\" fill=\"#939b98\" fontSize=\"10\" textAnchor={i===6?'end':'start'}>{v}</text>)}{vals.map((v,i)=><rect key={i} x={32+i*21.25} y=\"5\" width=\"22\" height=\"220\" fill=\"transparent\" onMouseEnter={()=>setHover(i)}/>)}{hover"'!==null&&<g><line x1={42+hover*21.25} x2={42+hover*21.25} y1="15" y2="221" stroke="#279a7c" strokeDasharray="3 3"/><circle cx={42+hover*21.25} cy={213-vals[hover]*.54*factor} r="4" fill="#249a7c" stroke="white" strokeWidth="2"/></g>}</svg>{hover!==null&&<div className="chart-tooltip" style={{left:`${Math.min(75,10+hover*2.5)}%`}}>{hover+1} июня <strong>₽ {Math.round(vals[hover]*factor*430).toLocaleString('"'ru-RU')}</strong></div>}</div></>}
function AppModal({title,children,close}:{title:string;children:React.ReactNode;close:()=>void}){return <div className=\"modal-backdrop\" onMouseDown={e=>{if(e.target===e.currentTarget)close();}}><section className=\"modal\" role=\"dialog\" aria-modal=\"true\" aria-label={title}><div className=\"modal-title\"><h2>{title}</h2><button className=\"icon-button\" onClick={close} aria-label=\"Закрыть\"><Icon name=\"close\"/></button></div>{children}</section></div>}
export function App(){
 const [board,setBoard]=useState('Обзор бизнеса');const [boards,setBoards]=useState(()=>{try{return JSON.parse(localStorage.getItem('pulse-boards')||'null')||['Обзор бизнеса','Маркетинг','Продажи'];}catch{return ['Обзор бизнеса','Маркетинг','Продажи'];}});
 const loadLayout=(name:string)=>{try{const parsed=JSON.parse(localStorage.getItem("'`pulse-layout-${name}`)||'"'null');return Array.isArray(parsed)&&parsed.every(w=>w&&titles[w.type as WidgetType]&&Number.isFinite(w.x)&&Number.isFinite(w.y)&&w.w>0&&w.h>0)?parsed:defaults.map(w=>({...w}));}catch{return defaults.map(w=>({...w}));}};
 const [widgets,setWidgets]=useState<Widget[]>(()=>loadLayout('Обзор бизнеса'));const [editing,setEditing]=useState(false);const [period,setPeriod]=useState('30 дней');const [modal,setModal]=useState<string|null>(null);const [menu,setMenu]=useState<string|null>(null);const [toast,setToast]=useState('');const [query,setQuery]=useState('');const [newBoard,setNewBoard]=useState('');const [activeNav,setActiveNav]=useState('Дашборды');const [drag,setDrag]=useState<{id:string;x:number;y:number;dx:number;dy:number}|null>(null);const [preview,setPreview]=useState<Widget|null>(null);const [mobileNav,setMobileNav]=useState(false);const [dateFrom,setDateFrom]=useState('2025-06-01');const [dateTo,setDateTo]=useState('2025-06-30');const [dateLabel,setDateLabel]=useState('1 июн — 30 июн, 2025');const [taskDone,setTaskDone]=useState<string[]>([]);const gridRef=useRef<HTMLDivElement>(null);const dragRef=useRef<{id:string;startX:number;startY:number;original:Widget;cell:number}|null>(null);
 useEffect(()=>{try{localStorage.setItem("'`pulse-layout-${board}`,JSON.stringify(widgets));}catch{setToast('"'Не удалось сохранить расположение в браузере');}},[widgets,board]);
 useEffect(()=>{if("'!toast)return;const timer=setTimeout(()=>setToast('"''),3500);return()=>clearTimeout(timer);},[toast]);
 useEffect(()=>{const handler=(e:KeyboardEvent)=>{if(e.key==='Escape'){setModal(null);setMenu(null);setDrag(null);setPreview(null);dragRef.current=null;}if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();setModal('search');}};window.addEventListener('keydown',handler);return()=>window.removeEventListener('keydown',handler);},[]);
 function switchBoard(name:string){setBoard(name);setWidgets(loadLayout(name));setActiveNav('Дашборды');setMobileNav(false);setModal(null);}
 function startDrag(e:ReactPointerEvent,w:Widget){if((e.target as HTMLElement).closest('button')||window.innerWidth<760)return;e.preventDefault();e.currentTarget.setPointerCapture(e.pointerId);dragRef.current={id:w.id,startX:e.clientX,startY:e.clientY,original:w,cell:((gridRef.current?.clientWidth||1000)+20)/12};setDrag({id:w.id,x:w.x,y:w.y,dx:0,dy:0});setMenu(null);}
 function moveDrag(e:ReactPointerEvent){const d=dragRef.current;if("'!d)return;const dx=e.clientX-d.startX,dy=e.clientY-d.startY;const x=Math.max(0,Math.min(12-d.original.w,d.original.x+Math.round(dx/d.cell))),y=Math.max(0,d.original.y+Math.round(dy/158));setDrag({id:d.id,x,y,dx,dy});setPreview({...d.original,x,y});}
 function endDrag(){if(drag&&preview){setWidgets(items=>relocate(items,drag.id,preview.x,preview.y));if(drag.dx||drag.dy)setToast('"'Расположение виджетов сохранено');}setDrag(null);setPreview(null);dragRef.current=null;}
 function addWidget(type:WidgetType){const metric=['revenue','orders','customers','conversion'].includes(type);const w=metric?3:['chart','projects'].includes(type)?8:4;const h=metric?1:2;let item:Widget={id:"'`${type}-${Date.now()}`,type,x:0,y:0,w,h};outer:for(let y=0;y<100;y++)for(let x=0;x<=12-w;x++){item={...item,x,y};if(!widgets.some(other=>overlap(item,other)))break outer;}setWidgets([...widgets,item]);setModal(null);setToast('"'Виджет добавлен на дашборд');}
 function exportReport(){const blob=new Blob(['\\ufeffПоказатель;Значение\\nВыручка;1284560\\nЗаказы;1842\\nНовые клиенты;648\\nКонверсия;3,62%'],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='pulse-report.csv';a.click();URL.revokeObjectURL(url);setToast('Отчёт скачан');}
